/*
 * The X (Twitter) post: the signature, the 280 limit, and the text.
 *
 * Three things here are the kind that fail silently and expensively.
 *
 *   - THE SIGNATURE. An OAuth 1.0a signature is wrong or right with nothing
 *     in between, and X answers a wrong one with a bare 401. The signer is
 *     checked against vectors generated by oauthlib - a separate, mature
 *     implementation of RFC 5849 - rather than against itself. The cases
 *     include the five characters encodeURIComponent famously leaves alone
 *     (! * ' ( )), because that is the bug this code is most likely to have
 *     and the one a round of ASCII-only testing would never show.
 *
 *   - THE LENGTH. X counts weighted characters, not characters: every emoji
 *     in these posts counts two. One unit over and the API rejects the whole
 *     post, so a day goes unposted rather than posting short.
 *
 *   - THE CLAIM. Each post costs real money now (X has had no free tier
 *     since February 2026), so a retried schedule that posts twice has spent
 *     twice and put the same leaderboard up twice.
 *
 * Pure; no emulator and no network.
 */
import fs from 'fs';
import path from 'path';
import { createHmac } from 'crypto';
import { fileURLToPath } from 'url';
const REPO = (f) => path.join(path.dirname(fileURLToPath(import.meta.url)), '..', f);
const fn = fs.readFileSync(REPO('functions/index.js'), 'utf8');

const t = [];
const ck = (ok, name, detail = '') => t.push([!!ok, name, detail]);
const eq = (name, got, want) => ck(got === want, name, `got ${JSON.stringify(got)} want ${JSON.stringify(want)}`);
const deq = (name, got, want) => ck(JSON.stringify(got) === JSON.stringify(want), name,
  `got ${JSON.stringify(got)} want ${JSON.stringify(want)}`);
const grab = (re, what) => { const m = fn.match(re); if (!m) throw new Error('could not extract ' + what); return m[0]; };
const func = (name) => grab(new RegExp(`^(?:async )?function ${name}\\(.*?\\) \\{\\n[\\s\\S]*?\\n\\}`, 'm'), name);
const konst = (name) => grab(new RegExp(`^const ${name} = [^\\n]*;`, 'm'), name);

// ---- the signature, against oauthlib ------------------------------------
{
  const sign = new Function('createHmac', `${func('pctEncode')}\n${func('oauthHeader')}\nreturn oauthHeader;`)(createHmac);
  const vectors = JSON.parse(fs.readFileSync(REPO('tests/oauth-vectors.json'), 'utf8'));
  ck(vectors.length >= 6, 'the vector file is there', String(vectors.length));
  const sigOf = (h) => (/oauth_signature="([^"]*)"/.exec(h) || [])[1];
  for (const v of vectors) {
    const h = sign('POST', v.url, { apiKey: v.apiKey, apiSecret: v.apiSecret,
      accessToken: v.accessToken, accessSecret: v.accessSecret }, v.nonce, v.timestamp);
    eq(`signature matches oauthlib: ${v.label}`, sigOf(h), v.signature);
  }
  // The vectors are only worth anything if a wrong signer fails them. One
  // character of one secret has to move the signature.
  {
    const v = vectors[0];
    const h = sign('POST', v.url, { apiKey: v.apiKey, apiSecret: v.apiSecret + 'x',
      accessToken: v.accessToken, accessSecret: v.accessSecret }, v.nonce, v.timestamp);
    ck(sigOf(h) !== v.signature, 'and a single wrong character fails them', sigOf(h));
  }
  // The header's own shape: X parses these, and a missing one is a 401.
  {
    const v = vectors[0];
    const h = sign('POST', v.url, { apiKey: v.apiKey, apiSecret: v.apiSecret,
      accessToken: v.accessToken, accessSecret: v.accessSecret }, v.nonce, v.timestamp);
    ck(h.startsWith('OAuth '), 'the header announces the scheme', h.slice(0, 20));
    for (const k of ['oauth_consumer_key', 'oauth_nonce', 'oauth_signature',
                     'oauth_signature_method', 'oauth_timestamp', 'oauth_token', 'oauth_version']) {
      ck(new RegExp(`${k}="[^"]+"`).test(h), `and carries ${k}`);
    }
    ck(/oauth_signature_method="HMAC-SHA1"/.test(h), 'signed with HMAC-SHA1, which is what X accepts');
    // The JSON body is NOT signed, so nothing about the post text may appear.
    ck(!/oauth_body_hash/.test(h),
       'and no body hash, which X does not implement and which would break the signature');
  }
}

// ---- percent-encoding ----------------------------------------------------
// The whole signature rests on this being RFC 3986 rather than
// encodeURIComponent, so it gets its own check rather than only being
// covered through a signature that could agree for other reasons.
{
  const pct = new Function(`${func('pctEncode')}\nreturn pctEncode;`)();
  eq('unreserved characters pass through untouched',
     pct("abcXYZ019-._~"), "abcXYZ019-._~");
  deq('the five encodeURIComponent misses are escaped',
      "!*'()".split('').map(pct), ['%21', '%2A', '%27', '%28', '%29']);
  eq('a space is %20, not a plus', pct('a b'), 'a%20b');
  eq('and the reserved ones are escaped too', pct('a+b/c=d&e'), 'a%2Bb%2Fc%3Dd%26e');
}

// ---- weighted length -----------------------------------------------------
{
  const w = new Function(`${func('tweetWeight')}\nreturn tweetWeight;`)();
  eq('plain latin weighs one each', w('hello'), 5);
  eq('nothing weighs nothing', w(''), 0);
  eq('and so does nothing at all', w(null), 0);
  eq('an emoji weighs two', w('\u{1F947}'), 2);
  // U+1F947 is one code point and two UTF-16 units; counting .length would
  // give the right answer here for the wrong reason, so check one that
  // differs: U+00E9 is one unit and weighs one.
  eq('a one-unit latin accent still weighs one', w('é'), 1);
  eq('a CJK character weighs two', w('中'), 2);
  // The boundaries of the light ranges, which is where an off-by-one lives.
  eq('U+10FF is inside the light range', w('ჿ'), 1);
  eq('U+1100 is outside it', w('ᄀ'), 2);
  eq('the general-punctuation window is light', w('‐'), 1);
}

// ---- the post text -------------------------------------------------------
const TWEET_MAX = Number(/^const TWEET_MAX = (\d+);/m.exec(fn)[1]);
const TWEET_ROWS = Number(/^const TWEET_ROWS = (\d+);/m.exec(fn)[1]);
const WORDS = Number(/^const MARATHON_WORD_COUNT = (\d+);/m.exec(fn)[1]);
const parts = [konst('HANDLE_MAX'), konst('SPRINT_EPOCH'), konst('MARATHON_WORD_COUNT'),
  konst('TWEET_ROWS'), konst('TWEET_LINK_WEIGHT'), konst('TWEET_PLACE'),
  func('puzzleNumber'), func('formatClock'), grab(/^const digestNum = [^\n]*;/m, 'digestNum'),
  func('tweetWeight'), func('tweetName'), func('tweetDate'), func('tweetRow'),
  grab(/^const tweetBody = [^\n]*;/m, 'tweetBody'), func('buildTweet')].join('\n\n');
// X_LINK and TWEET_MAX are left out of the lift and injected. X_LINK so both
// settings of the one constant that changes what a post costs get exercised;
// TWEET_MAX so the row-dropping loop can be driven at all. At the real 280 it
// cannot fire: a handle is capped at HANDLE_MAX, so five rows of the widest
// possible everything still come in under the limit - which is the invariant
// the case below this one pins. Shrinking the budget is how you test the
// safety net without pretending to data the game cannot produce.
const builder = (link, max = TWEET_MAX) => new Function('LINK', 'MAX',
  `const X_LINK = LINK; const TWEET_MAX = MAX;\n${parts}\nreturn buildTweet;`)(link, max);
const build = builder('');
const weigh = new Function(`${func('tweetWeight')}\nreturn tweetWeight;`)();

const sprintRows = (n) => Array.from({ length: n }, (_, i) =>
  ({ username: 'PLAYER' + (i + 1), score: 500 - i * 50, elapsedMs: 41200 + i * 1000 }));
const marathonRows = (n) => Array.from({ length: n }, (_, i) =>
  ({ username: 'PLAYER' + (i + 1), score: 9120 - i * 400, marathonWords: 20 - i }));

{
  const out = build({ mode: 'sprint', dateStr: '2026-11-07', rows: sprintRows(3), words: ['CRANE'] });
  const lines = out.split('\n').filter(Boolean);
  ck(/Lexathon Sprint #\d+/.test(lines[0]), 'the Sprint post names the mode and its number', lines[0]);
  ck(/Nov 7/.test(lines[0]), 'and the day it reports on', lines[0]);
  ck(lines[1].startsWith('\u{1F947}'), 'first place takes the gold medal', lines[1]);
  ck(lines[2].startsWith('\u{1F948}'), 'second the silver', lines[2]);
  ck(lines[3].startsWith('\u{1F949}'), 'third the bronze', lines[3]);
  ck(/41\.2s/.test(lines[1]), 'a Sprint row carries the clock', lines[1]);
  ck(/500/.test(lines[1]), 'and the score', lines[1]);
  eq('and the answer goes last, the way the Discord digest puts it first',
     lines.at(-1), 'Word: CRANE');
}
{
  const out = build({ mode: 'marathon', dateStr: '2026-11-02', rows: marathonRows(3), words: [] });
  const lines = out.split('\n').filter(Boolean);
  ck(/Lexathon Marathon/.test(lines[0]), 'the Marathon post names the mode', lines[0]);
  ck(!/#\d/.test(lines[0]),
     'and gives it no number, because it ran monthly before it ran weekly', lines[0]);
  ck(/Week of Nov 2/.test(lines[0]), 'carrying the week instead', lines[0]);
  ck(new RegExp(`20/${WORDS}`).test(lines[1]), 'a Marathon row carries words solved', lines[1]);
  ck(/9,120/.test(lines[1]), 'and the week score, thousands separated', lines[1]);
  ck(!/Word:/.test(out), 'and never the answers: twenty words do not fit in a post', out);
  // Handed them anyway, it still must not print them - words: [] alone would
  // pass with the mode check deleted.
  const given = build({ mode: 'marathon', dateStr: '2026-11-02', rows: marathonRows(3),
    words: ['CRANE', 'SLOTH', 'PRISM'] });
  ck(!/Word:|CRANE|SLOTH|PRISM/.test(given),
     'not even when the week\u2019s words are passed in', given);
}
{
  // Fourth and fifth place have no medal, and the post stops at five even
  // though the query fetches ten.
  const out = build({ mode: 'sprint', dateStr: '2026-11-07', rows: sprintRows(10), words: [] });
  const rows = out.split('\n').filter((l) => /^(\u{1F947}|\u{1F948}|\u{1F949}|\d+\.)/u.test(l));
  eq('a post is at most five deep', rows.length, TWEET_ROWS);
  ck(rows[3].startsWith('4.'), 'fourth place is a numeral', rows[3]);
  ck(rows[4].startsWith('5.'), 'and so is fifth', rows[4]);
}

// ---- the 280 limit -------------------------------------------------------
// The limit is weighted, and every row in these posts starts with a
// two-weight medal or a numeral. Handles are capped at HANDLE_MAX, so the
// worst realistic case is five of them at full width.
{
  const wide = Array.from({ length: TWEET_ROWS }, (_, i) =>
    ({ username: 'WWWWWWWWWWWW', score: 999999 - i, elapsedMs: 3599900 }));
  for (const link of ['', 'https://lexathon.gg']) {
    const out = builder(link)({ mode: 'sprint', dateStr: '2026-11-07', rows: wide, words: ['CRANE'] });
    const budget = link ? TWEET_MAX - 23 : TWEET_MAX;
    ck(weigh(out.replace(link, '')) <= budget,
       `the widest realistic post fits, link=${JSON.stringify(link)}`,
       `${weigh(out.replace(link, ''))} of ${budget}`);
  }
}
eq('the limit in the source is X\u2019s own 280', TWEET_MAX, 280);
{
  // The safety net, driven at a budget small enough to need it. Five rows
  // cannot fit in 120, so some have to go - and the ones that go are the
  // ones at the bottom.
  const out = builder('', 120)({ mode: 'marathon', dateStr: '2026-11-02',
    rows: marathonRows(TWEET_ROWS), words: [] });
  ck(weigh(out) <= 120, 'an over-long post is trimmed to fit', String(weigh(out)));
  const kept = out.split('\n').filter((l) => /\d+\/\d+/.test(l));
  ck(kept.length >= 1 && kept.length < TWEET_ROWS,
     'by dropping rows off the bottom', String(kept.length));
  ck(kept[0].startsWith('\u{1F947}'), 'the leader is the row that survives', kept[0]);
  ck(!/PLAYER5/.test(out), 'and last place is the first to go', out);
}
{
  // Never to nothing, though. A budget too small for even one row still
  // posts the leader rather than a header with an empty space under it.
  const out = builder('', 10)({ mode: 'marathon', dateStr: '2026-11-02',
    rows: marathonRows(TWEET_ROWS), words: [] });
  eq('a budget too small for any row still keeps one',
     out.split('\n').filter((l) => /\d+\/\d+/.test(l)).length, 1);
}
{
  // A link is budgeted at a flat t.co width whether or not it is measured,
  // so at a budget tight enough to matter the linked post must keep FEWER
  // rows than the bare one. Without the subtraction both keep the same
  // number and the post goes out over the limit.
  const rowsAt = (link) => builder(link, 120)({ mode: 'marathon', dateStr: '2026-11-02',
    rows: marathonRows(TWEET_ROWS), words: [] }).split('\n').filter((l) => /\d+\/\d+/.test(l)).length;
  ck(rowsAt('https://lexathon.gg') < rowsAt(''),
     'the link is paid for out of the row budget, not added on top of it',
     `${rowsAt('https://lexathon.gg')} rows with a link, ${rowsAt('')} without`);
}
{
  const out = builder('https://lexathon.gg')(
    { mode: 'sprint', dateStr: '2026-11-07', rows: sprintRows(3), words: ['CRANE'] });
  eq('with a link configured it goes on its own last line',
     out.split('\n').at(-1), 'https://lexathon.gg');
  ck(!build({ mode: 'sprint', dateStr: '2026-11-07', rows: sprintRows(3), words: ['CRANE'] })
      .includes('lexathon.gg'),
     'and with none configured the post carries no URL at all');
}
// The default costs thirteen times less per post, so which one is committed
// is worth pinning rather than discovering on a bill.
eq('X_LINK ships empty, which is the cheap rate', /^const X_LINK = "([^"]*)";/m.exec(fn)[1], '');

// ---- a handle is the last free text a stranger controls ------------------
{
  const nameOf = (out) => out.split('\n')[2].replace(/^\u{1F947} /u, '').split(' ')[0];
  const one = (username) => build({ mode: 'sprint', dateStr: '2026-11-07',
    rows: [{ username, score: 500, elapsedMs: 1000 }], words: [] });
  ck(!/\n/.test(one('AB\nCD').split('\n\n')[1]),
     'a newline inside a handle cannot split a row in two', JSON.stringify(one('AB\nCD')));
  ck(/player/.test(one('   ')), 'an all-whitespace handle falls back to a word', one('   '));
  ck(/player/.test(one('')), 'and so does an empty one', one(''));
  ck(/player/.test(one(null)), 'and a missing one', one(null));
  // The live filter caps handles at HANDLE_MAX, but /runs documents keep the
  // name as it was when the run happened, and the cap has moved before.
  const HANDLE_MAX = Number(/^const HANDLE_MAX = (\d+);/m.exec(fn)[1]);
  const long = 'W'.repeat(HANDLE_MAX + 20);
  ck(!one(long).includes(long), 'a handle longer than the cap is cut, not printed whole');
  eq('and cut to exactly the cap', nameOf(one(long)).length, HANDLE_MAX);
  // The handle filter admits no @ and no dot, so neither a mention nor a URL
  // can reach a post - which is also what keeps the cheap rate reliable.
  const filter = grab(/\.replace\(\/\[\^a-zA-Z0-9_\\s-\]\/g, ""\)/, 'the handle filter');
  ck(!!filter, 'handles are filtered to letters, digits, underscore, hyphen and space', filter);
}

// ---- an unsolved Sprint ---------------------------------------------------
{
  const out = build({ mode: 'sprint', dateStr: '2026-11-07',
    rows: [{ username: 'NOPE', score: 0, elapsedMs: null }], words: [] });
  ck(/ - /.test(out), 'a player who never solved gets a dash, not an instant 0.0s', out);
  ck(!/0\.0s/.test(out), '...which would have put them at the top of the clock column', out);
}

// ---- parking the posting --------------------------------------------------
// Read off the environment rather than from defineSecret params, which is
// what lets the two schedules deploy with no X secrets in Secret Manager at
// all. An unset environment is the ordinary state and must park cleanly.
{
  const cr = new Function(`${func('xCredentials')}\nreturn xCredentials;`)();
  const NAMES = ['X_API_KEY', 'X_API_SECRET', 'X_ACCESS_TOKEN', 'X_ACCESS_SECRET'];
  const env = (over = {}) => Object.assign(
    Object.fromEntries(NAMES.map((n, i) => [n, 'abcd'[i]])), over);
  ck(cr(env()) !== null, 'all four set is a configured poster');
  eq('and nothing set at all parks it, which is the shipped state', cr({}), null);
  for (const n of NAMES) {
    eq(`"off" for ${n} parks the posting`, cr(env({ [n]: 'off' })), null);
    eq(`and ${n} unset does too`, cr(env({ [n]: '' })), null);
  }
  eq('OFF in any case parks it too', cr(env({ X_ACCESS_SECRET: 'OFF' })), null);
  deq('and the credentials come back trimmed', cr(env({ X_API_KEY: ' a ' })),
      { apiKey: 'a', apiSecret: 'b', accessToken: 'c', accessSecret: 'd' });
  // The whole point: nothing here may be a defineSecret the deploy requires.
  for (const n of NAMES) {
    ck(!new RegExp(`defineSecret\\("${n}"\\)`).test(fn),
       `${n} is not a secret the deploy demands exist`);
  }
}

// ---- the paste-ready draft -----------------------------------------------
// The whole point of the draft is that a person posts it by hand, which is
// not an API request and so is not billed - the URL surcharge that keeps
// X_LINK empty does not apply to it at all.
//
// It is STORED, not sent. The Discord webhooks are deliberately untouched:
// they go to channels other people read.
{
  const saver = (link) => {
    const writes = [];
    const db = { collection: (c) => ({ doc: (id) => ({
      set: async (v) => { writes.push({ path: `${c}/${id}`, ...v }); } }) }) };
    const body = new Function('db', 'FieldValue', 'console', 'LINK', 'DATA', `
      const X_LINK = LINK; const TWEET_MAX = ${TWEET_MAX};
      ${parts}
      ${konst('DRAFT_LINK')}
      ${func('prettyDigestDate')}
      ${func('saveDraft')}
      return saveDraft(DATA);`);
    return async (data) => {
      writes.length = 0;
      await body(db, { serverTimestamp: () => 'TS' }, { log: () => {} }, link, data);
      return writes[0];
    };
  };
  const save = saver('');
  const w = await save({ mode: 'sprint', dateStr: '2026-11-07', rows: sprintRows(5), words: ['CRANE'] });

  eq('the draft is stored, not posted anywhere', w.path, 'adminDrafts/sprint_2026-11-07');
  eq('under the board it is for', w.mode, 'sprint');
  eq('and the day it reports on', w.key, '2026-11-07');
  ck(/^Sprint \u00B7 /.test(w.label), 'with a label naming both', w.label);
  ck(/2026/.test(w.label), 'in a form a person reads', w.label);

  // THE POINT: the link is there even though X_LINK is empty.
  eq('the text carries the link on its own last line', w.text.split('\n').at(-1), 'https://lexathon.gg');
  ck(/\u{1F947} PLAYER1/u.test(w.text), 'with the board above it', w.text.split('\n')[2]);
  ck(/Word: CRANE/.test(w.text), 'and the answer', w.text);
  ck(weigh(w.text) <= TWEET_MAX, 'and it still fits a post', `${weigh(w.text)} of ${TWEET_MAX}`);
  const bare = build({ mode: 'sprint', dateStr: '2026-11-07', rows: sprintRows(5), words: ['CRANE'] });
  ck(weigh(w.text) > weigh(bare), 'the link costs it real room', `${weigh(w.text)} vs ${weigh(bare)}`);

  // Turning the automated link on must not change the draft: it has one
  // already, and two would be two t.co widths out of the same 280.
  const withLink = await saver('https://lexathon.gg')(
    { mode: 'sprint', dateStr: '2026-11-07', rows: sprintRows(5), words: ['CRANE'] });
  eq('the draft is the same whatever X_LINK is set to', withLink.text, w.text);

  // A deterministic id, which is what makes a retried schedule harmless:
  // it rewrites the same document with the same text. No claim needed,
  // unlike a post, which leaves a trace of having happened twice.
  const again = await save({ mode: 'sprint', dateStr: '2026-11-07', rows: sprintRows(5), words: ['CRANE'] });
  eq('a second run overwrites the same document', again.path, w.path);
  eq('with the same text', again.text, w.text);

  const m = await save({ mode: 'marathon', dateStr: '2026-11-02', rows: marathonRows(5), words: [] });
  eq('the Marathon draft gets its own document', m.path, 'adminDrafts/marathon_2026-11-02');
  ck(/^Marathon \u00B7 /.test(m.label), 'labelled as Marathon', m.label);
  ck(/lexathon\.gg/.test(m.text), 'and carries the link as well');
}

// ---- who may read them ----------------------------------------------------
// Gated on a VERIFIED email against a secret. Unverified matters: an
// unverified address on a token is a claim the provider never checked.
{
  const gate = async (token, secret) => {
    const read = [];
    const db = { collection: (c) => ({ orderBy: (f, d) => ({ limit: (n) => ({
      get: async () => { read.push(`${c} ${f} ${d} ${n}`); return { docs: [] }; } }) }) }) };
    class HttpsError extends Error {
      constructor(code, msg) { super(msg); this.code = code; }
    }
    // The callable, unwrapped: onCall and readableFailures are the harness
    // around it, and what is on trial is the gate inside.
    const whole = grab(/^exports\.getDrafts = onCall\([\s\S]*?\n\}\)\);$/m, 'getDrafts');
    const inner = whole
      .replace(/^exports\.getDrafts = onCall\(\{[^}]*\}, readableFailures\("[^"]*", /, '')
      .replace(/\)\);$/, '');
    ck(/^async \(request\) => \{/.test(inner), 'the callable body is findable', inner.slice(0, 40));
    const body = new Function('db', 'ADMIN_EMAIL', 'HttpsError', 'requireAuth', 'TOKEN',
      `const fn = ${inner};\nreturn fn({ auth: { uid: 'u1', token: TOKEN } });`);
    try {
      await body(db, { value: () => secret }, HttpsError, () => 'u1', token);
      return { ok: true, read };
    } catch (e) { return { ok: false, code: e.code, read }; }
  };
  const good = { email: 'me@example.com', email_verified: true };
  eq('the right verified address is let in', (await gate(good, 'me@example.com')).ok, true);
  eq('and case does not matter', (await gate({ ...good, email: 'Me@Example.COM' }, 'me@example.com')).ok, true);
  eq('nor does surrounding space', (await gate(good, '  me@example.com ')).ok, true);
  eq('a different address is refused', (await gate({ ...good, email: 'you@example.com' }, 'me@example.com')).code,
     'permission-denied');
  eq('the right address UNVERIFIED is refused',
     (await gate({ email: 'me@example.com', email_verified: false }, 'me@example.com')).code, 'permission-denied');
  eq('and a token with no email at all is refused',
     (await gate({ email_verified: true }, 'me@example.com')).code, 'permission-denied');
  // An unset secret must close the door, not open it to the empty address.
  // The !want and !got guards in the source are belt-and-braces: `got !==
  // want` already refuses both of these on its own, so removing either
  // changes no behaviour. They stay because "fails closed when unset" should
  // be legible in the condition rather than deduced from it.
  eq('an unset ADMIN_EMAIL refuses everyone',
     (await gate({ email: '', email_verified: true }, '')).code, 'permission-denied');
  eq('including a real address', (await gate(good, '')).code, 'permission-denied');
  // Nothing is read on the refusal paths.
  deq('a refused call reads nothing', (await gate(good, 'you@example.com')).read, []);
  deq('and an allowed one reads the newest first',
      (await gate(good, 'me@example.com')).read, ['adminDrafts at desc 10']);
}
// The collection is closed to every client, so the callable is the only way
// in and the gate cannot be stepped around by reading it directly.
{
  const rules = fs.readFileSync(REPO('firestore.rules'), 'utf8').replace(/\r\n/g, '\n');
  const block = rules.slice(rules.indexOf('match /adminDrafts/'), rules.indexOf('match /adminDrafts/') + 120);
  ck(/allow read, write: if false;/.test(block), 'adminDrafts is server-only in the rules', block.trim());
}

// ---- the Discord webhooks are left exactly as they were -------------------
// The draft is an admin screen, not a third channel. Nothing about it may
// add a destination to a secret other people's servers are reading from.
{
  ck(!/DISCORD_DRAFT_WEBHOOK/.test(fn), 'no draft webhook exists');
  const webhooks = [...fn.matchAll(/defineSecret\("(DISCORD_[A-Z_]+)"\)/g)].map((m) => m[1]).sort();
  deq('and the webhook secrets are the two that were already there', webhooks,
      ['DISCORD_SPRINT_WEBHOOK', 'DISCORD_TRIFECTA_WEBHOOK']);
}

// ---- the claim, which is what stops a retry posting twice ----------------
{
  const src = `${func('claimPost')}\n${func('deliverTweet')}`;
  const run = async (opts) => {
    const docs = new Map((opts.already || []).map((k) => [k, true]));
    const log = [];
    const ref = (id) => ({
      id,
      delete: async () => { docs.delete(id); log.push('released ' + id); },
    });
    const db = {
      collection: () => ({ doc: (id) => ref(id) }),
      runTransaction: async (f) => f({
        get: async (r) => ({ exists: docs.has(r.id) }),
        set: (r) => { docs.set(r.id, true); log.push('claimed ' + r.id); },
      }),
    };
    const posted = [];
    const postTweet = async (text) => {
      posted.push(text);
      if (opts.fail) throw new Error('X returned 403');
    };
    const body = new Function('db', 'FieldValue', 'console', 'postTweet', 'OPTS', `
      ${src}
      return deliverTweet(OPTS);`);
    await body(db, { serverTimestamp: () => 'TS' }, { log: () => {}, error: () => {} },
      postTweet, { mode: 'sprint', key: '2026-11-07', label: 'l', creds: {},
                   build: async () => 'text' });
    return { docs, log, posted };
  };
  const first = await run({});
  eq('the first run posts once', first.posted.length, 1);
  deq('having claimed the day under the channel name "x"',
      [...first.docs.keys()], ['sprint_2026-11-07_x']);
  ck(first.log[0].startsWith('claimed'), 'claiming BEFORE the post, not after', first.log.join(','));

  const already = await run({ already: ['sprint_2026-11-07_x'] });
  eq('a day already claimed is not posted a second time', already.posted.length, 0);

  const failed = await run({ fail: true });
  eq('a failed post releases the day again', [...failed.docs.keys()].length, 0);
  deq('claimed then released, so tomorrow can retry it', failed.log,
      ['claimed sprint_2026-11-07_x', 'released sprint_2026-11-07_x']);
}
// "x" cannot collide with a Discord destination, which is what makes one
// claim collection safe for both.
ck(/\.slice\(0, 12\)/.test(func('channelId')),
   'a Discord channel id is twelve hex digits, so "x" is never one of them', func('channelId'));

// ---- the Marathon row, which had the score field wrong -------------------
// postWeeklyDigest reads /users, and a user document has no `score` field at
// all - it keeps the week under marathonScore. Handed over raw, every row
// rendered "0". Run against the field names a user document really carries.
{
  const row = new Function(`${func('marathonRow')}\nreturn marathonRow;`)();
  const userDoc = { username: 'JFEKETE', marathonScore: 9120, marathonWords: 20,
                    marathonKey: '2026-11-02', bestMarathonScore: 9120 };
  deq('a user document becomes a row the renderers understand', row(userDoc),
      { username: 'JFEKETE', score: 9120, marathonWords: 20 });
  ck(row(userDoc).score !== 0, '...and not the zero that reading r.score gave');
  deq('a player with nothing yet reads as zero rather than NaN', row({ username: 'NEW' }),
      { username: 'NEW', score: 0, marathonWords: 0 });
  // The query site must actually use it, or the fix is a function nobody calls.
  const weekly = fn.slice(fn.indexOf('exports.postWeeklyDigest'), fn.indexOf('function marathonRow'));
  ck(/rows: snap\.docs\.map\(\(d\) => marathonRow\(d\.data\(\)\)\)/.test(weekly),
     'and the weekly schedule maps its documents through it',
     (weekly.match(/[^\n]*rows:[^\n]*/) || [''])[0].trim());
}

// ---- the admin screen -----------------------------------------------------
{
  const html = fs.readFileSync(REPO('index.html'), 'utf8').replace(/\r\n/g, '\n');
  ck(/id="admin-modal"/.test(html), 'there is a modal to put the drafts in');
  ck(/id="admin-drafts"/.test(html), 'and somewhere inside it for them to go');
  ck(/httpsCallable\(cloudFunctions, "getDrafts"\)/.test(html),
     'the page reaches them through the callable, not the collection');
  ck(/if \(location\.hash === "#admin"\) window\.openAdmin\(\);/.test(html),
     'opened by the hash, after auth has resolved',
     (html.match(/[^\n]*location\.hash === "#admin"[^\n]*/) || [''])[0].trim());
  // No door for the people who cannot walk through it. The hash is not the
  // security - getDrafts is - but a visible button would be a puzzle for
  // every player who found it.
  ck(!/openAdmin\(\)"/.test(html), 'and by nothing else: no button anywhere opens it');

  const fnSrc = (re) => (html.match(re) || [''])[0];
  const open = fnSrc(/        window\.openAdmin = async function\(\) \{\n[\s\S]*?\n        \};/);
  ck(open.length > 200, 'the opener is findable', String(open.length));
  ck(/escapeHtml\(String\(d\.text/.test(open),
     'the draft text is escaped: it is built from player handles', open.match(/[^\n]*escapeHtml[^\n]*/)[0].trim());
  ck(/escapeHtml\(String\(d\.label/.test(open), 'and so is the label');
  const caught = (open.match(/catch \(e\) \{[\s\S]*?\n            \}/) || [''])[0];
  ck(/box\.innerText =/.test(caught),
     'a refusal shows a message rather than throwing into the console', caught.trim());
  ck(/e\.message/.test(caught), 'and shows what the refusal actually said', caught.trim());
  ck(/if \(!currentUser\)/.test(open), 'and a signed-out visitor is told to sign in, not left on "Loading..."');

  const copy = fnSrc(/        window\.copyDraft = function\(i\) \{\n[\s\S]*?\n        \};/);
  ck(/copyToClipboard\(String\(d\.text/.test(copy),
     'copy puts the RAW text on the clipboard, not the escaped markup',
     copy.match(/[^\n]*copyToClipboard[^\n]*/)[0].trim());
  ck(/flashButtonLabel/.test(copy), 'and says whether it worked, like every other copy button here');
}

// ---- the schedules are actually wired -------------------------------------
{
  for (const [name, why, own] of [
    ['postDailyDigest', 'the Sprint board', 'DISCORD_SPRINT_WEBHOOK'],
    ['postWeeklyDigest', 'the Marathon board', 'DISCORD_TRIFECTA_WEBHOOK'],
  ]) {
    const start = fn.indexOf(`exports.${name}`);
    const body = fn.slice(start, start + 3200);
    ck(/deliverTweet\(/.test(body), `${name} can post ${why} to X`);
    ck(/await saveDraft\(/.test(body), `${name} always stores a draft of ${why}`);
    // The draft is unconditional: there is no configuration that turns it
    // off and therefore no state in which the morning produces nothing.
    ck(!/nowhere to post/.test(body),
       `${name} has no "nowhere to post" exit any more, because the draft is always a destination`);

    // The secrets the schedule demands exist at deploy time. Exactly the
    // one webhook each already had - adding any made both functions
    // undeployable until four unused secrets were created by hand.
    const secrets = (body.match(/secrets: \[[^\]]*\]/) || [''])[0];
    eq(`${name} asks for exactly the secret it already had`, secrets, `secrets: [${own}]`);
  }
  // Nothing anywhere may make an X credential a deploy-time requirement.
  ck(/const creds = xCredentials\(\);/.test(fn),
     'the credentials come from the environment, not from a secret param',
     (fn.match(/const creds = [^\n]*/) || [''])[0].trim());
}

let bad = 0;
for (const [ok, name, detail] of t) {
  if (!ok) bad++;
  console.log((ok ? 'PASS' : 'FAIL').padEnd(6) + name + (ok ? '' : '  -> ' + detail));
}
console.log(bad ? `\n${bad} of ${t.length} FAILED` : `\nAll ${t.length} passed`);
process.exit(bad ? 1 : 0);
